        $dateValid=(bool)preg_match('/^\d{4}-\d{2}-\d{2}$/',$date);$monthValid=(bool)preg_match('/^\d{4}-\d{2}$/',$month);$year=max(2000,min(2100,(int)($_GET['year']??($dateValid?substr($date,0,4):($monthValid?substr($month,0,4):date('Y'))))));
