    private function runAccount(string $path,string $method): never
    {
        $u=Auth::requireUser();RequestContext::set(RequestContext::all()+['user_guid'=>$u['user_guid']]);if($method==='POST')Http::verifyCsrf();
        if($path==='/account/subscription')$this->accountSubscription($u);
        if($path==='/account/library')$this->accountLibrary($u);
        if($path==='/account/devices')$this->accountDevices($u);
        if($method==='POST'&&preg_match('#^/account/devices/([0-9a-f-]{36})/revoke$#i',$path,$m))$this->accountDeviceRevoke($u,$m[1]);
        if($method==='POST'&&preg_match('#^/account/(saved-articles|bookmarks|clips|history|offline|notifications)/clear$#',$path,$m))$this->accountClear($u,$m[1]);
        if($method==='POST'&&preg_match('#^/account/saved-articles/([0-9a-f-]{36})/(update|delete)$#i',$path,$m))$this->accountSavedAction($u,$m[1],$m[2]);
        if($method==='POST'&&preg_match('#^/account/bookmarks/([0-9a-f-]{36})/(update|delete)$#i',$path,$m))$this->accountBookmarkAction($u,$m[1],$m[2]);
        if($method==='POST'&&preg_match('#^/account/clips/([A-Za-z0-9_-]+)/(update|delete)$#',$path,$m))$this->accountClipAction($u,$m[1],$m[2]);
        if($method==='POST'&&preg_match('#^/account/history/([0-9a-f-]{36})/delete$#i',$path,$m))$this->accountHistoryDelete($u,$m[1]);
        if($method==='POST'&&preg_match('#^/account/offline/([0-9a-f-]{36})/delete$#i',$path,$m))$this->accountOfflineDelete($u,$m[1]);
        if($method==='POST'&&preg_match('#^/account/notifications/([0-9a-f-]{36})/(read|delete)$#i',$path,$m))$this->accountNotificationAction($u,$m[1],$m[2]);
        if($path==='/account')$this->accountOverview($u);
        $map=['/account/saved-articles'=>'saved','/account/bookmarks'=>'bookmarks','/account/clips'=>'clips','/account/history'=>'history','/account/offline'=>'offline','/account/notifications'=>'notifications'];if(isset($map[$path]))$this->accountList($u,$map[$path]);http_response_code(404);View::layout('Not Found','<section class="empty-state"><h1>Account page not found</h1></section>',['brand'=>$this->brandName(),'account'=>true]);
    }
