    private function accountOverviewMetrics(string $uidBin,string $userGuid): array
    {
        $key='account:overview:v2:'.RequestContext::tenantGuid().':'.$userGuid;
        $cached=RedisStore::getJson($key);
        if(is_array($cached))return $cached;
        $tb=TenantData::tenantBin();
        $row=Store::one('SELECT
            (SELECT COUNT(*) FROM ep_saved_articles WHERE tenant_guid=? AND platform_user_guid=?) AS saved_articles,
            (SELECT COUNT(*) FROM ep_bookmarks WHERE tenant_guid=? AND platform_user_guid=?) AS bookmarks,
            (SELECT COUNT(*) FROM ep_clips WHERE tenant_guid=? AND platform_user_guid=?) AS clips,
            (SELECT COUNT(*) FROM ep_history WHERE tenant_guid=? AND platform_user_guid=?) AS history,
            (SELECT COUNT(DISTINCT edition_guid) FROM ep_offline_items WHERE tenant_guid=? AND platform_user_guid=? AND status="READY" AND (expires_at IS NULL OR expires_at>UTC_TIMESTAMP(6))) AS offline,
            (SELECT COUNT(*) FROM ep_notifications WHERE tenant_guid=? AND (platform_user_guid=? OR platform_user_guid IS NULL) AND status="UNREAD") AS notifications',[$tb,$uidBin,$tb,$uidBin,$tb,$uidBin,$tb,$uidBin,$tb,$uidBin,$tb,$uidBin])?:[];
        $metrics=[
            'saved_articles'=>(int)($row['saved_articles']??0),
            'bookmarks'=>(int)($row['bookmarks']??0),
            'clips'=>(int)($row['clips']??0),
            'history'=>(int)($row['history']??0),
            'offline'=>(int)($row['offline']??0),
            'notifications'=>(int)($row['notifications']??0),
        ];
        RedisStore::setJson($key,$metrics,RedisStore::ttlWithJitter(10,2));
        return $metrics;
    }

    private function assetUrlFromBinary(mixed $assetGuid,int $ttl=3600): ?string
    {
        if(!is_string($assetGuid)||$assetGuid==='')return null;
        try{$guid=Uuid::fromBinary($assetGuid);}catch(\Throwable){return null;}
        return $guid?'/media/'.Media::token($guid,$ttl):null;
    }

