            elseif($type==='bookmarks'){$rows=Store::all('SELECT b.target_guid,b.bookmark_type,b.note,b.created_at,p.page_number,e.edition_guid,e.slug,e.edition_date,pub.name publication_name,a.asset_guid thumb_asset_guid FROM ep_bookmarks b LEFT JOIN ep_pages p ON UPPER(b.bookmark_type)="PAGE" AND p.tenant_guid=b.tenant_guid AND p.page_guid=b.target_guid LEFT JOIN ep_editions e ON e.tenant_guid=p.tenant_guid AND e.edition_guid=p.edition_guid LEFT JOIN ep_publications pub ON pub.tenant_guid=e.tenant_guid AND pub.publication_guid=e.publication_guid LEFT JOIN ep_page_assets a ON a.tenant_guid=p.tenant_guid AND a.page_guid=p.page_guid AND a.asset_type="THUMB" WHERE b.tenant_guid=? AND b.platform_user_guid=? ORDER BY b.created_at DESC LIMIT 100',[TenantData::tenantBin(),$uid]);foreach($rows as$r){$count++;$target=Uuid::fromBinary($r['target_guid']);$eg=$r['edition_guid']?Uuid::fromBinary($r['edition_guid']):null;$page=(int)($r['page_number']??0);$img=$this->assetUrlFromBinary($r['thumb_asset_guid']??null);$url=!empty($r['slug'])?'/edition/'.$this->e($r['slug']).'/page/'.$page:'#';$manage='<form method="post" action="/account/bookmarks/'.$target.'/update" class="record-form">'.$this->csrf().'<label>Note<textarea name="note" rows="3" maxlength="500">'.$this->e($r['note']??'').'</textarea></label><button class="btn small">Save note</button></form><form method="post" action="/account/bookmarks/'.$target.'/delete" data-confirm="Remove this bookmark?">'.$this->csrf().'<button class="record-action danger">Remove</button></form>';$html.=$this->accountCard($url,$img,$page?'Page '.$page:'Bookmark','BOOKMARK',$r['publication_name']?:ucfirst((string)$r['bookmark_type']),!empty($r['edition_date'])?date('d M Y',strtotime($r['edition_date'])):date('d M Y',strtotime($r['created_at'])),$r['note']??'',$manage);}}
