    private function adminNavigation(): never
    {
        $this->requireNavigationEditor();
        try{ReaderNavigation::ensureGlobalScope();}catch(\Throwable$e){$this->adminError('Reader Navigation database upgrade is required: '.$e->getMessage());}
        $scopes=ReaderNavigation::listScopes();$requested=(string)($_GET['scope']??'');$scope=$scopes[0]??null;
        if($requested!=='')foreach($scopes as$candidate)if((string)$candidate['nav_scope_guid']===$requested){$scope=$candidate;break;}
        if(!$scope)$this->adminError('No Reader Navigation scope is available');$scopeGuid=(string)$scope['nav_scope_guid'];
        $items=ReaderNavigation::items($scopeGuid);$preview=ReaderNavigation::preview($scopeGuid);$versions=ReaderNavigation::versions($scopeGuid,12);
        $pubs=TenantData::toGuidRows(Store::all('SELECT publication_guid,name FROM ep_publications WHERE tenant_guid=? AND status="ACTIVE" ORDER BY is_default DESC,name',[TenantData::tenantBin()]),['publication_guid']);
        $cities=TenantData::toGuidRows(Store::all('SELECT city_guid,name FROM ep_cities WHERE tenant_guid=? AND status="ACTIVE" ORDER BY name',[TenantData::tenantBin()]),['city_guid']);
        $langs=TenantData::toGuidRows(Store::all('SELECT language_guid,name,code FROM ep_languages WHERE tenant_guid=? AND status="ACTIVE" ORDER BY name',[TenantData::tenantBin()]),['language_guid']);
        $opt=function(array$rows,string$id,string$label){$h='<option value="">Any / Global</option>';foreach($rows as$r)$h.='<option value="'.$this->e($r[$id]).'">'.$this->e($r[$label]).'</option>';return$h;};
