        $rows=SemanticNews::adminArticles();$editGuid=trim((string)($_GET['edit']??''));$edit=null;$editAuthors=[];$editTopics=[];$editEntities=[];if($editGuid!==''&&Uuid::isValid($editGuid)){$edit=Store::one('SELECT * FROM ep_articles WHERE tenant_guid=? AND article_guid=?',[TenantData::tenantBin(),Uuid::toBinary($editGuid)]);if($edit){$edit=TenantData::guidRow($edit,['article_guid','publication_guid','city_guid','language_guid','section_guid','edition_guid','page_guid','created_by_user_guid','updated_by_user_guid']);$editAuthors=array_column(SemanticNews::authorsForArticle($editGuid),'author_guid');$editTopics=array_column(SemanticNews::topicsForArticle($editGuid),'topic_guid');$editEntities=array_column(SemanticNews::entitiesForArticle($editGuid),'entity_guid');}}
        $pubs=TenantData::toGuidRows(Store::all('SELECT publication_guid,name FROM ep_publications WHERE tenant_guid=? AND status="ACTIVE" ORDER BY is_default DESC,name',[TenantData::tenantBin()]),['publication_guid']);$cities=TenantData::toGuidRows(Store::all('SELECT city_guid,name FROM ep_cities WHERE tenant_guid=? AND status="ACTIVE" ORDER BY name',[TenantData::tenantBin()]),['city_guid']);$langs=TenantData::toGuidRows(Store::all('SELECT language_guid,name,code FROM ep_languages WHERE tenant_guid=? AND status="ACTIVE" ORDER BY name',[TenantData::tenantBin()]),['language_guid']);$sections=TenantData::toGuidRows(Store::all('SELECT section_guid,name FROM ep_sections WHERE tenant_guid=? AND status="ACTIVE" ORDER BY sort_order,name',[TenantData::tenantBin()]),['section_guid']);$authors=SemanticNews::adminAuthors();$topics=SemanticNews::adminTopics();$entities=SemanticNews::adminEntities();$ocrPages=SemanticNews::recentOcrPages(80);
