    private function articleEditor(?array $edit,array $pubs,array $cities,array $langs,array $sections,array $authors,array $topics,array $entities,array $ocrPages,array $selectedAuthors,array $selectedTopics,array $selectedEntities): string
    {
        $action=$edit?'/admin/articles/'.$edit['article_guid'].'/update':'/admin/articles';$title=$edit?'Edit article':'Create article';$sourceOptions='<option value="">No OCR source — newsroom copy</option>';foreach($ocrPages as$p){$label=$p['publication_name'].' · '.date('d M Y',strtotime((string)$p['edition_date'])).' · Page '.(int)$p['page_number'];$sourceOptions.='<option value="'.$this->e($p['page_guid']).'"'.(($edit['page_guid']??'')===$p['page_guid']?' selected':'').'>'.$this->e($label).'</option>';}
        $h='<section class="panel semantic-editor"><div class="section-head"><div><span class="eyebrow">'.($edit?'EDITORIAL WORKSPACE':'NEW ARTICLE').'</span><h2>'.$title.'</h2><p class="muted">OCR is a starting point only. Review headline, body, byline, sources and disclosures before publishing.</p></div>'.($edit?'<a class="text-btn" href="/admin/articles">New draft</a>':'').'</div><form method="post" action="'.$this->e($action).'" class="form-stack">'.$this->csrf().'<label>OCR source page<select name="source_page_guid">'.$sourceOptions.'</select><small>When creating a new article, OCR text is used only if the body field is empty.</small></label><label>Headline<input name="title" value="'.$this->e($edit['title']??'').'" maxlength="250" required></label><label>Slug<input name="slug" value="'.$this->e($edit['slug']??'').'" placeholder="auto from headline"></label><label>Deck / standfirst<textarea name="deck" rows="3">'.$this->e($edit['deck']??'').'</textarea></label><label>Article body<textarea name="body" rows="16" required>'.$this->e($edit['body']??'').'</textarea></label><div class="form-grid"><label>Publication<select name="publication_guid" required><option value="">Select</option>'.$this->semanticOptions($pubs,'publication_guid','name',(string)($edit['publication_guid']??'')).'</select></label><label>City<select name="city_guid"><option value="">None</option>'.$this->semanticOptions($cities,'city_guid','name',(string)($edit['city_guid']??'')).'</select></label><label>Language<select name="language_guid"><option value="">Default</option>'.$this->semanticOptions($langs,'language_guid','name',(string)($edit['language_guid']??'')).'</select></label><label>Section<select name="section_guid"><option value="">None</option>'.$this->semanticOptions($sections,'section_guid','name',(string)($edit['section_guid']??'')).'</select></label></div><label>Authors<select name="authors[]" multiple size="5">'.$this->semanticMultiOptions($authors,'author_guid','name',$selectedAuthors).'</select><small>At least one active author is required before publication. Create newsroom/desk authors under Authors when appropriate.</small></label><label>Topics<select name="topics[]" multiple size="5">'.$this->semanticMultiOptions($topics,'topic_guid','name',$selectedTopics).'</select></label><label>Entities<select name="entities[]" multiple size="5">'.$this->semanticMultiOptions($entities,'entity_guid','name',$selectedEntities).'</select></label><details class="processing-advanced"><summary>Discovery, source transparency & AI disclosure</summary><div class="form-stack"><label>Primary image URL<input name="primary_image_url" value="'.$this->e($edit['primary_image_url']??'').'" placeholder="/path/to/article-image.webp"></label><label>Translation key<input name="translation_key" value="'.$this->e($edit['translation_key']??'').'" placeholder="same key across translated versions"></label><label>Sources & reporting notes<textarea name="source_notes" rows="5">'.$this->e($edit['source_notes']??'').'</textarea></label><label>Correction / update note<textarea name="correction_note" rows="4">'.$this->e($edit['correction_note']??'').'</textarea></label><label class="check"><input type="checkbox" name="ai_assisted" value="1"'.(!empty($edit['ai_assisted'])?' checked':'').'> AI-assisted tools were used in this article workflow</label><label>AI disclosure<textarea name="ai_disclosure" rows="3">'.$this->e($edit['ai_disclosure']??'').'</textarea></label></div></details><div class="form-actions"><button class="btn primary">'.($edit?'Save article':'Create draft').'</button>'.($edit&&$edit['status']==='PUBLISHED'?'<a class="btn ghost" href="/article/'.$this->e($edit['slug']).'" target="_blank" rel="noopener">View public</a>':'').'</div></form></section>';return$h;
    }

