    private function adminEditions(string $method): never
    {
        if($method==='POST'){$this->createEdition();}
        $pubs=TenantData::toGuidRows(Store::all('SELECT publication_guid,name FROM ep_publications WHERE tenant_guid=? AND status="ACTIVE" ORDER BY name',[TenantData::tenantBin()]),['publication_guid']);
        $cities=TenantData::toGuidRows(Store::all('SELECT city_guid,name FROM ep_cities WHERE tenant_guid=? AND status="ACTIVE" ORDER BY name',[TenantData::tenantBin()]),['city_guid']);
        $langs=TenantData::toGuidRows(Store::all('SELECT language_guid,name FROM ep_languages WHERE tenant_guid=? AND status="ACTIVE" ORDER BY name',[TenantData::tenantBin()]),['language_guid']);
        $where=[];$params=[];$q=trim((string)($_GET['q']??''));$status=strtoupper(trim((string)($_GET['status']??'')));$page=max(1,(int)($_GET['page']??1));$perPage=25;$date=trim((string)($_GET['date']??''));
        if($q!==''){$where[]='(e.title LIKE ? OR p.name LIKE ? OR e.slug LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}
        if(in_array($status,['DRAFT','PROCESSING','NEEDS_ATTENTION','READY','SCHEDULED','PUBLISHED','ARCHIVED','TRASHED'],true)){$where[]='e.status=?';$params[]=$status;}
        if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$where[]='e.edition_date=?';$params[]=$date;}
        if($status==='')$where[]='e.status NOT IN ("ARCHIVED","TRASHED")';
        $filter=$where?implode(' AND ',$where):'1=1';
        $total=TenantData::countEditionsForAdmin($filter,$params);$page=min($page,max(1,(int)ceil($total/$perPage)));
        $rows=TenantData::editionsForAdmin($filter,$params,$perPage,($page-1)*$perPage);
        $options=fn($rows,$key)=>implode('',array_map(fn($r)=>'<option value="'.$this->e($r[$key]).'">'.$this->e($r['name']).'</option>',$rows));
        $appTz=(string)Config::get('app.timezone','Asia/Kolkata');$defaults=ProcessingRecovery::defaults();
        $html='<section class="admin-head editions-head"><div><span class="eyebrow">PUBLISHING</span><h1>Editions</h1><p class="muted">Manage, process, recover, schedule and publish newspaper editions from one operational workspace.</p></div><button class="btn primary" type="button" data-open-editor-target="edition-create-form">+ Add edition</button></section>';
        if(!empty($_GET['notice']))$html.='<div class="alert success" role="status">'.$this->e(substr((string)$_GET['notice'],0,300)).'</div>';
        if(!empty($_GET['updated']))$html.='<div class="alert success">Edition updated.</div>';if(!empty($_GET['scheduled']))$html.='<div class="alert success">Publication schedule updated.</div>';if(!empty($_GET['reprocessing']))$html.='<div class="alert success">Reprocessing queued. The previous processing history has been retained.</div>';
        $html.='<section class="panel editions-library"><div class="editions-toolbar"><form method="get" class="editions-filter-form"><label class="editions-search"><span class="sr-only">Search editions</span><input type="search" name="q" value="'.$this->e($q).'" placeholder="Search editions…"></label><label><span class="sr-only">Status</span><select name="status"><option value="">Active editions</option>';
        foreach(['DRAFT','PROCESSING','NEEDS_ATTENTION','READY','SCHEDULED','PUBLISHED','ARCHIVED','TRASHED'] as$s)$html.='<option value="'.$s.'"'.($status===$s?' selected':'').'>'.ucwords(strtolower(str_replace('_',' ',$s))).'</option>';
        $html.='</select></label><label><span class="sr-only">Edition date</span><input type="date" name="date" value="'.$this->e($date).'"></label><button class="btn ghost">Filter</button>'.(($q!==''||$status!==''||$date!=='')?'<a class="text-btn" href="/admin/editions">Clear</a>':'').'</form><span class="pill">'.count($rows).' of '.$total.' editions</span></div>'.$this->editionTable($rows).'</section>';
        $html.='<nav class="edition-pagination" aria-label="Edition pages">';
        foreach(['Previous'=>max(1,$page-1),'Next'=>min(max(1,(int)ceil($total/$perPage)),$page+1)] as$label=>$target){$href='/admin/editions?'.http_build_query(['q'=>$q,'status'=>$status,'date'=>$date,'page'=>$target]);$html.=$target===$page?'<span aria-disabled="true">'.$label.'</span>':'<a class="btn ghost" href="'.$this->e($href).'">'.$label.'</a>';}
        $html.='<span>Page '.$page.' of '.max(1,(int)ceil($total/$perPage)).'</span></nav>';
        $html.='<form id="edition-create-form" method="post" enctype="multipart/form-data" class="form-stack editor-source edition-create-form" data-editor-title="Add edition">'.$this->csrf().'<div class="form-grid"><label>Publication<select name="publication_guid" required><option value="">Select…</option>'.$options($pubs,'publication_guid').'</select></label><label>Edition date<input type="date" name="edition_date" value="'.date('Y-m-d').'" required></label><label>City<select name="city_guid"><option value="">None</option>'.$options($cities,'city_guid').'</select></label><label>Language<select name="language_guid"><option value="">None</option>'.$options($langs,'language_guid').'</select></label></div><label>Title<input name="title" placeholder="Defaults to publication + date"></label><label>PDF<input type="file" name="pdf" accept="application/pdf" required></label><fieldset class="edition-publish-choice"><legend>Publishing</legend><label class="edition-radio"><input type="radio" name="publish_mode" value="MANUAL" checked><span><strong>Save as draft</strong><small>Process the edition, then publish manually.</small></span></label><label class="edition-radio"><input type="radio" name="publish_mode" value="AUTO_READY"><span><strong>Publish when ready</strong><small>Automatically publish after processing completes.</small></span></label><label class="edition-radio"><input type="radio" name="publish_mode" value="SCHEDULED"><span><strong>Schedule publishing</strong><small>Publish at a chosen date/time after processing is ready.</small></span></label><div class="edition-schedule-fields" data-edition-schedule-fields hidden><label>Publish date & time<input type="datetime-local" name="scheduled_at"></label><label>Timezone<select name="schedule_timezone"><option value="'.$this->e($appTz).'">'.$this->e($appTz).'</option><option value="UTC"'.($appTz==='UTC'?' selected':'').'>UTC</option></select></label></div></fieldset><div class="drawer-actions"><button type="button" class="btn ghost" data-close-record-editor>Cancel</button><button class="btn primary" data-edition-create-submit>Create edition</button></div><p class="muted">Processing starts immediately through the supervised queue. Scheduled/auto publishing waits for a successful READY state.</p></form>';
        // Default values are embedded once and reused by each reprocess drawer.
        $html.='<script type="application/json" id="edition-processing-defaults">'.json_encode($defaults,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_SLASHES).'</script>';
        View::layout('Editions',$html,['brand'=>$this->brandName(),'admin'=>true]);
    }

    private function createEdition(): void
    {
        $pub=(string)($_POST['publication_guid']??'');$date=(string)($_POST['edition_date']??'');
        if(!preg_match('/^[0-9a-f-]{36}$/i',$pub)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$this->adminError('Invalid publication or date');
        if(empty($_FILES['pdf'])||($_FILES['pdf']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)$this->adminError('PDF upload failed');
        if(($_FILES['pdf']['size']??0)>300*1024*1024)$this->adminError('PDF exceeds 300 MB');
        $mime=(new \finfo(FILEINFO_MIME_TYPE))->file($_FILES['pdf']['tmp_name']);if($mime!=='application/pdf')$this->adminError('Uploaded file is not a PDF');
        $g=Uuid::v7();$p=Store::one('SELECT name,slug FROM ep_publications WHERE tenant_guid=? AND publication_guid=?',[TenantData::tenantBin(),Uuid::toBinary($pub)]);if(!$p)$this->adminError('Publication not found');
        $slug=$this->slug($p['slug'].'-'.$date.'-'.substr(str_replace('-','',$g),-6));$dir=dirname(__DIR__).'/storage/uploads/'.RequestContext::tenantGuid().'/'.$g;@mkdir($dir,0775,true);$dst=$dir.'/source.pdf';if(!move_uploaded_file($_FILES['pdf']['tmp_name'],$dst))$this->adminError('Could not store the uploaded PDF');$rel=str_replace(dirname(__DIR__).'/storage/','',$dst);
        $city=!empty($_POST['city_guid'])?Uuid::toBinary($_POST['city_guid']):null;$lang=!empty($_POST['language_guid'])?Uuid::toBinary($_POST['language_guid']):null;$u=Auth::user();
        $publishMode=strtoupper(trim((string)($_POST['publish_mode']??'MANUAL')));if(!in_array($publishMode,['MANUAL','AUTO_READY','SCHEDULED'],true))$publishMode='MANUAL';
        $scheduleTz=null;$scheduledAt=null;if($publishMode==='SCHEDULED'){[$scheduledAt,$scheduleTz]=$this->parseScheduledInput((string)($_POST['scheduled_at']??''),(string)($_POST['schedule_timezone']??Config::get('app.timezone','Asia/Kolkata')));}
        Store::exec('INSERT INTO ep_editions(edition_guid,tenant_guid,publication_guid,city_guid,language_guid,edition_date,title,slug,source_pdf_path,status,publish_mode,schedule_timezone,scheduled_at,created_by_user_guid,updated_by_user_guid,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,"DRAFT",?,?,?,?,?,NOW(6),NOW(6))',[Uuid::toBinary($g),TenantData::tenantBin(),Uuid::toBinary($pub),$city,$lang,$date,trim((string)($_POST['title']??''))?:$p['name'].' '.$date,$slug,$rel,$publishMode,$scheduleTz,$scheduledAt,$u?Uuid::toBinary($u['user_guid']):null,$u?Uuid::toBinary($u['user_guid']):null]);
        $jobGuid=QueueService::enqueueEditionRender($g,'normal',['processing_profile'=>'default','publish_intent'=>$publishMode]);Audit::log('edition.created','edition',$g,'SUCCESS',['slug'=>$slug,'publish_mode'=>$publishMode,'scheduled_at'=>$scheduledAt,'schedule_timezone'=>$scheduleTz,'job_guid'=>$jobGuid]);PlatformClient::instance()->usage(RequestContext::tenantGuid(),'EPAPER.EDITIONS',1);Http::redirect('/admin/editions');
    }

    private function editionTable(array $rows): string
    {
        $h='<div class="table-wrap editions-table-wrap"><table class="editions-table"><thead><tr><th>Edition</th><th>Date</th><th>Processing</th><th>Publish status</th><th>Schedule</th><th>Actions</th></tr></thead><tbody>';
        foreach($rows as$r){
            $r=TenantData::guidRow($r,['edition_guid']);$guid=$r['edition_guid'];$status=(string)($r['status']??'DRAFT');$process=$this->editionProcessingPresentation($r);$publish=$this->editionPublishPresentation($r);$schedule=$this->editionSchedulePresentation($r);$error=trim((string)($r['latest_processing_error']??$r['processing_error']??''));
            $title=trim((string)($r['title']??''))?:($r['publication_name']??'Edition');$sub=trim((string)($r['publication_name']??'').(!empty($r['city_name'])?' · '.$r['city_name']:'').(!empty($r['language_name'])?' · '.$r['language_name']:''));
            $actions='<div class="edition-actions console-action-cluster" role="group" aria-label="Actions for '.$this->e($title).'"><a class="console-icon-action is-view" href="/edition/'.$this->e($r['slug']).'/page/1" title="View edition" aria-label="View '.$this->e($title).'">'.View::icon('eye').'</a><button class="console-icon-action is-edit" type="button" data-open-editor-target="edit-'.$guid.'" title="Edit metadata" aria-label="Edit '.$this->e($title).'">'.View::icon('edit').'</button>';
            if($status==='NEEDS_ATTENTION')$actions.='<button class="edition-reprocess-primary" type="button" data-open-editor-target="reprocess-'.$guid.'" title="Reprocess edition">'.View::icon('refresh').'<span>Reprocess</span></button>';
            elseif($status==='DRAFT')$actions.='<form class="console-icon-form" method="post" action="/admin/editions/'.$guid.'/process-now">'.$this->csrf().'<button class="console-icon-action is-process" title="Process now" aria-label="Process now">'.View::icon('refresh').'</button></form>';
            elseif($status==='PROCESSING')$actions.='<a class="console-icon-action is-view" href="/admin/processing/'.$guid.'" title="View processing" aria-label="View processing">'.View::icon('activity').'</a>';
            if($status==='READY')$actions.='<button class="console-icon-action is-schedule" type="button" data-open-editor-target="publish-'.$guid.'" title="Publish or schedule" aria-label="Publish or schedule">'.View::icon('clock').'</button>';
            if(in_array($status,['ARCHIVED','TRASHED'],true))$actions.='<form class="console-icon-form" method="post" action="/admin/editions/'.$guid.'/restore">'.$this->csrf().'<button class="console-icon-action is-restore" title="Restore edition" aria-label="Restore '.$this->e($title).'">'.View::icon('restore').'</button></form>';
            elseif($status!=='PROCESSING')$actions.='<form class="console-icon-form" method="post" action="/admin/editions/'.$guid.'/archive" data-confirm="Archive this edition? Publishing intent will be cleared; processing/audit history is retained.">'.$this->csrf().'<button class="console-icon-action is-archive" title="Archive edition" aria-label="Archive '.$this->e($title).'">'.View::icon('archive').'</button></form>';
            if(in_array($status,['PROCESSING','NEEDS_ATTENTION'],true)){
                $actions.='<form class="inline" method="post" action="/admin/editions/'.$guid.'/recover">'.$this->csrf().'<button class="console-icon-action is-process" title="Recover unfinished work" aria-label="Recover unfinished work">'.View::icon('refresh').'</button></form><form class="inline" method="post" action="/admin/editions/'.$guid.'/cancel" data-confirm="Stop processing at the next safe checkpoint?">'.$this->csrf().'<button class="console-icon-action is-delete" title="Cancel processing" aria-label="Cancel processing">'.View::icon('stop').'</button></form>';
                if((int)($r['processing_active_count']??0)===0)$actions.='<button class="btn small" type="button" data-open-editor-target="reprocess-'.$guid.'">Reprocess</button>';
            }
            if(in_array($status,['PROCESSING','NEEDS_ATTENTION'],true))$actions.='<form class="inline" method="post" action="/admin/editions/'.$guid.'/process-immediately">'.$this->csrf().'<button class="console-icon-action is-process" title="Process immediately" aria-label="Process immediately">'.View::icon('play').'</button></form>';
            if(!in_array($status,['PUBLISHED','SCHEDULED','TRASHED'],true))$actions.='<form class="inline" method="post" action="/admin/editions/'.$guid.'/trash" data-confirm="Move this edition to Trash? Active work will be cancelled safely. Files are retained for Restore.">'.$this->csrf().'<button class="console-icon-action is-delete" title="Move to Trash" aria-label="Move to Trash">'.View::icon('trash').'</button></form>';
            $manage='';
            if($status==='READY')$manage.='<button type="button" class="record-action" data-open-editor-target="reprocess-'.$guid.'">Reprocess edition</button>';
            if((string)($r['publish_mode']??'MANUAL')==='SCHEDULED'&&!empty($r['scheduled_at']))$manage.='<form method="post" action="/admin/editions/'.$guid.'/unschedule">'.$this->csrf().'<button class="record-action">Cancel schedule</button></form>';
            if($manage!=='')$actions.=$this->recordMenu($manage);
            $actions.='</div>';
            $editForm='<form id="edit-'.$guid.'" method="post" action="/admin/editions/'.$guid.'/update" class="record-form editor-source" data-editor-title="Edit '.$this->e($title).'">'.$this->csrf().'<label>Title<input name="title" value="'.$this->e($title).'" required></label><label>Edition date<input type="date" name="edition_date" value="'.$this->e($r['edition_date']).'" required></label><div class="drawer-actions"><button type="button" class="btn ghost" data-close-record-editor>Cancel</button><button class="btn primary">Save metadata</button></div></form>';
            $reprocess=$this->editionReprocessForm($r,$error);$publishForm=$this->editionPublishForm($r);$rowClass=$status==='NEEDS_ATTENTION'?' edition-row-attention':'';
            $h.='<tr class="'.$rowClass.'"><td data-label="Edition"><div class="edition-identity"><strong>'.$this->e($title).'</strong><small>'.$this->e($sub).'</small><span>'.(int)($r['page_count']??0).' pages'.((int)($r['processing_run_count']??0)>0?' · '.(int)$r['processing_run_count'].' processing run'.((int)$r['processing_run_count']===1?'':'s'):'').'</span></div></td><td data-label="Date">'.$this->e(date('d M Y',strtotime((string)$r['edition_date']))).'</td><td data-label="Processing"><span class="status '.$this->e($process['class']).'">'.$this->e($process['label']).'</span><small class="edition-status-note">'.$this->e($process['note']).'</small>'.($error!==''&&$status==='NEEDS_ATTENTION'?'<button type="button" class="edition-error-link" data-open-editor-target="reprocess-'.$guid.'">View issue</button>':'').'</td><td data-label="Publish"><span class="status '.$this->e($publish['class']).'">'.$this->e($publish['label']).'</span><small class="edition-status-note">'.$this->e($publish['note']).'</small></td><td data-label="Schedule">'.$schedule.'</td><td data-label="Actions" class="table-actions">'.$actions.$editForm.$reprocess.$publishForm.'</td></tr>';
        }
        if(!$rows)$h.='<tr><td colspan="6"><div class="master-empty"><strong>No editions match this view</strong><p>Change the filters or add a new edition.</p></div></td></tr>';
        return$h.'</tbody></table></div>';
    }

    private function editionProcessingPresentation(array $r): array
    {
        $status=(string)($r['status']??'DRAFT');$job=strtoupper((string)($r['processing_status']??''));$progress=(float)($r['processing_progress']??0);
        if($status==='TRASHED')return['label'=>'Stopped','class'=>'archived','note'=>'Restore to process again'];
        if($status==='NEEDS_ATTENTION')return['label'=>'Needs attention','class'=>'failed','note'=>'Recovery available'];
        if($status==='PROCESSING'||in_array($job,['QUEUED','RUNNING','RETRY_WAIT'],true))return['label'=>!empty($r['processing_stalled'])?'Waiting too long':($job==='QUEUED'?'Queued':'Processing'),'class'=>!empty($r['processing_stalled'])?'failed':'processing','note'=>isset($r['stage_summary'])?($r['overall_progress'].'% overall · '.$r['stage_summary']):'Waiting for processing'];
        if(in_array($status,['READY','SCHEDULED','PUBLISHED','ARCHIVED'],true)&&(int)($r['page_count']??0)>0)return['label'=>'Processed','class'=>'ready','note'=>(int)$r['page_count'].' pages ready'];
        if($job==='FAILED')return['label'=>'Failed','class'=>'failed','note'=>'Open recovery'];
        return['label'=>'Not processed','class'=>'draft','note'=>'Waiting to process'];
    }

    private function editionPublishPresentation(array $r): array
    {
        $status=(string)($r['status']??'DRAFT');$mode=(string)($r['publish_mode']??'MANUAL');
        if($status==='PUBLISHED')return['label'=>'Published','class'=>'published','note'=>!empty($r['published_at'])?date('d M · H:i',strtotime((string)$r['published_at'])):'Live'];
        if($status==='TRASHED')return['label'=>'In Trash','class'=>'archived','note'=>'Files retained for Restore'];
        if($status==='ARCHIVED')return['label'=>'Archived','class'=>'archived','note'=>'Not in public library'];
        if($mode==='SCHEDULED')return['label'=>'Scheduled','class'=>'scheduled','note'=>$status==='NEEDS_ATTENTION'?'Waiting for successful reprocess':'Will publish when ready'];
        if($mode==='AUTO_READY')return['label'=>'Auto publish','class'=>'scheduled','note'=>$status==='READY'?'Publishing on scheduler':'After processing succeeds'];
        return['label'=>'Draft','class'=>'draft','note'=>$status==='READY'?'Ready to publish':'Not public'];
    }

    private function editionSchedulePresentation(array $r): string
    {
        if((string)($r['publish_mode']??'MANUAL')!=='SCHEDULED'||empty($r['scheduled_at']))return'<span class="edition-no-schedule">Not scheduled</span>';
        $appTz=(string)Config::get('app.timezone','Asia/Kolkata');$tz=(string)($r['schedule_timezone']??$appTz);
        try{$dt=new \DateTimeImmutable((string)$r['scheduled_at'],new \DateTimeZone($appTz));$dt=$dt->setTimezone(new \DateTimeZone($tz));$label=$dt->format('d M Y · h:i A');}catch(\Throwable){$label=(string)$r['scheduled_at'];}
        return'<div class="edition-schedule"><strong>'.$this->e($label).'</strong><small>'.$this->e($tz).'</small></div>';
    }

    private function editionReprocessForm(array $r,string $error): string
    {
        $guid=(string)$r['edition_guid'];$defaults=ProcessingRecovery::defaults();$recommend=ProcessingRecovery::recommended($error);$reason=implode(' ',$recommend['reasons']);$smartDefault=ProcessingRecovery::manualSmartDefault();
        $tiles='';foreach([256,384,512,768,1024] as$tile)$tiles.='<option value="'.$tile.'"'.((int)$defaults['tile_size']===$tile?' selected':'').'>'.$tile.' px</option>';
        return'<form id="reprocess-'.$guid.'" method="post" action="/admin/editions/'.$guid.'/reprocess" class="form-stack editor-source edition-reprocess-form" data-editor-title="Reprocess edition">'.$this->csrf().'<div class="edition-reprocess-summary"><span class="eyebrow">PREVIOUS PROCESSING</span><strong>'.($error!==''?'Issue detected':'Manual reprocess').'</strong><p>'.$this->e($error!==''?$error:'Create a new processing attempt while retaining previous job history.').'</p></div><label class="edition-radio"><input type="radio" name="reprocess_mode" value="default" checked><span><strong>Use default settings</strong><small>Retry with the current Publisher Control processing defaults.</small></span></label><label class="edition-radio"><input type="radio" name="reprocess_mode" value="custom"><span><strong>Customize & reprocess</strong><small>Override settings only for this processing run.</small></span></label><label class="check edition-recovery-check"><input type="checkbox" name="recommended_corrections" value="1"'.($error!==''&&$smartDefault?' checked':'').'> Automatically apply recommended corrections</label><p class="edition-recovery-reason">'.$this->e($reason).'</p><div class="edition-custom-processing" data-custom-processing hidden><div class="form-grid"><label>PDF DPI<input type="number" name="pdf_dpi" min="96" max="400" value="'.(int)$defaults['pdf_dpi'].'"></label><label>Preview width<input type="number" name="preview_width" min="640" max="3000" value="'.(int)$defaults['preview_width'].'"></label><label>Thumbnail width<input type="number" name="thumbnail_width" min="120" max="1200" value="'.(int)$defaults['thumbnail_width'].'"></label><label>Deep Zoom tile<select name="tile_size">'.$tiles.'</select></label><label>OCR timeout (seconds)<input type="number" name="ocr_timeout_seconds" min="30" max="900" value="'.(int)$defaults['ocr_timeout_seconds'].'"></label><label>OCR languages<input name="ocr_languages" value="'.$this->e((string)$defaults['ocr_languages']).'" placeholder="auto or mar+eng"></label></div><label class="check"><input type="checkbox" name="auto_language" value="on"'.((string)$defaults['auto_language']==='on'?' checked':'').'> Use edition language OCR profile</label></div><div class="drawer-actions"><button type="button" class="btn ghost" data-close-record-editor>Cancel</button><button class="btn primary">Start reprocessing</button></div><p class="muted edition-history-link">A new processing pipeline is created. Previous attempts remain available. <a href="/admin/processing/'.$guid.'">View processing history →</a> · <a href="/admin/settings/processing">Recovery defaults →</a></p></form>';
    }

    private function editionPublishForm(array $r): string
    {
        $guid=(string)$r['edition_guid'];$appTz=(string)Config::get('app.timezone','Asia/Kolkata');
        return'<form id="publish-'.$guid.'" method="post" action="/admin/editions/'.$guid.'/schedule" class="form-stack editor-source edition-publish-form" data-editor-title="Publish edition">'.$this->csrf().'<label class="edition-radio"><input type="radio" name="publish_action" value="now" checked><span><strong>Publish now</strong><small>Make this READY edition public immediately.</small></span></label><label class="edition-radio"><input type="radio" name="publish_action" value="schedule"><span><strong>Schedule publishing</strong><small>Publish automatically at the selected date/time.</small></span></label><div class="edition-schedule-fields" data-edition-publish-schedule hidden><label>Publish date & time<input type="datetime-local" name="scheduled_at"></label><label>Timezone<select name="schedule_timezone"><option value="'.$this->e($appTz).'">'.$this->e($appTz).'</option><option value="UTC"'.($appTz==='UTC'?' selected':'').'>UTC</option></select></label></div><div class="drawer-actions"><button type="button" class="btn ghost" data-close-record-editor>Cancel</button><button class="btn primary">Continue</button></div></form>';
    }

    private function adminEditionAction(string $guid,string $action): never
    {
        $guard='epdi_ops_'.substr(hash('sha256',RequestContext::tenantGuid().'|'.$guid),0,40);if((int)Store::value('SELECT GET_LOCK(?,0)',[$guard])!==1)$this->adminError('Another edition action is in progress.');
        if(EditionOperations::active($guid))$this->adminError('Processing jobs are still active. Use Cancel processing or Recover first.');

        $bin=Uuid::toBinary($guid);$row=Store::one('SELECT status,title,edition_date,slug FROM ep_editions WHERE tenant_guid=? AND edition_guid=?',[TenantData::tenantBin(),$bin]);if(!$row)$this->adminError('Edition not found');
        if($action==='update'){$title=trim((string)($_POST['title']??''));$date=trim((string)($_POST['edition_date']??''));if($title===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$this->adminError('Title and a valid edition date are required');Store::exec('UPDATE ep_editions SET title=?,edition_date=?,updated_at=NOW(6),version=version+1 WHERE tenant_guid=? AND edition_guid=?',[$title,$date,TenantData::tenantBin(),$bin]);Audit::log('edition.updated','edition',$guid,'SUCCESS',['edition_date'=>$date]);if((string)$row['status']==='PUBLISHED'){EditionManifest::invalidate((string)($row['slug']??''),$guid);RuntimeCache::broadcast(RequestContext::tenantGuid(),['public-editions']);RuntimeCache::queueWarm(RequestContext::tenantGuid(),$guid);}Http::redirect('/admin/editions?updated=1');}
        if($action==='archive'){if($row['status']==='TRASHED')$this->adminError('Restore the trashed edition first.');if(in_array($row['status'],['PROCESSING','QUEUED','RUNNING'],true))$this->adminError('A processing edition cannot be archived. Wait for processing or recover the job first.');Store::exec('UPDATE ep_editions SET status="ARCHIVED",publish_mode="MANUAL",scheduled_at=NULL,schedule_timezone=NULL,updated_at=NOW(6),version=version+1 WHERE tenant_guid=? AND edition_guid=?',[TenantData::tenantBin(),$bin]);Audit::log('edition.archived','edition',$guid);EditionManifest::invalidate((string)$row['slug'],$guid);RuntimeCache::broadcast(RequestContext::tenantGuid(),['public-editions','reader_state']);Http::redirect('/admin/editions?updated=1');}
        if($action==='restore'){if(!in_array($row['status'],['ARCHIVED','TRASHED'],true))$this->adminError('Only archived or trashed editions can be restored');EditionOperations::clearStop($guid);Store::exec('UPDATE ep_editions SET status="DRAFT",publish_mode="MANUAL",scheduled_at=NULL,schedule_timezone=NULL,updated_at=NOW(6),version=version+1 WHERE tenant_guid=? AND edition_guid=?',[TenantData::tenantBin(),$bin]);Audit::log('edition.restored','edition',$guid);Http::redirect('/admin/editions?updated=1');}
        $this->adminError('Unsupported edition action');
    }

    private function adminProcessNow(string $guid): never
    {
        if(!RateLimiter::allow('process-now:'.RequestContext::tenantGuid(),6,300))$this->adminError('Processing actions are temporarily rate-limited.');
        try{$jobGuid=QueueService::enqueueEditionRender($guid,'high',['processing_profile'=>'default']);}
        catch(\RuntimeException $e){$this->adminError($e->getMessage());}
        Audit::log('edition.processing_enqueued','edition',$guid,'SUCCESS',['job_guid'=>$jobGuid]);Http::redirect('/admin/editions?reprocessing=1');
    }

    private function adminEditionRecovery(string $guid,string $action): never
    {
        $role=strtoupper((string)(Auth::currentMembership()['role_key']??''));
        if(in_array($action,['trash','delete'],true)&&!in_array($role,['OWNER','ADMIN','PUBLISHER_ADMIN','EDITOR'],true))$this->adminError('Your role cannot move editions to Trash.');
        if(!RateLimiter::allow('edition-recovery:'.RequestContext::tenantGuid(),20,300))$this->adminError('Too many recovery requests. Try again shortly.');
        try{
            if(in_array($action,['recover','process-immediately'],true)){DirectRecovery::request($guid);$launched=DirectRecovery::launch();$notice=$launched?'Immediate processing requested. Open processing details to confirm runner activity and progress.':'Recovery request saved. The direct recovery worker must be started by your hosting administrator; open processing details for status.';}
            else{$result=EditionOperations::requestStop($guid,in_array($action,['trash','delete'],true)?'trash':'cancel');$notice=$result['pending']?'Stop requested. '.$result['pending'].' running job(s) will stop at the next checkpoint. Refresh to check progress.':($result['intent']==='trash'?'Edition moved to Trash. Files are retained for Restore.':'Processing stopped. Use Reprocess when ready.');}
        }catch(\RuntimeException $e){$this->adminError($e->getMessage());}
        Http::redirect('/admin/editions?notice='.rawurlencode($notice));
    }

    private function adminReprocess(string $guid): never
    {
        if(!RateLimiter::allow('reprocess:'.RequestContext::tenantGuid(),5,300))$this->adminError('Reprocessing is temporarily rate-limited');
        $edition=Store::one('SELECT status,publish_mode FROM ep_editions WHERE tenant_guid=? AND edition_guid=?',[TenantData::tenantBin(),Uuid::toBinary($guid)]);if(!$edition)$this->adminError('Edition not found');
        if(in_array((string)$edition['status'],['PUBLISHED','ARCHIVED','SCHEDULED','TRASHED'],true))$this->adminError('Reprocessing is available for draft, failed or ready unpublished editions. Published/scheduled editions require a staged replacement workflow.');
        $active=(int)Store::value('SELECT COUNT(*) FROM ep_processing_jobs WHERE tenant_guid=? AND edition_guid=? AND status IN ("QUEUED","RUNNING","RETRY_WAIT")',[TenantData::tenantBin(),Uuid::toBinary($guid)]);if($active>0)$this->adminError('This edition already has an active processing pipeline.');
        $mode=(string)($_POST['reprocess_mode']??'default');if(!in_array($mode,['default','custom'],true))$mode='default';
        $issue=ProcessingRecovery::lastIssue($guid);$recommended=!empty($_POST['recommended_corrections'])?ProcessingRecovery::recommended($issue['error']??null):['overrides'=>[],'reasons'=>[]];$overrides=$recommended['overrides'];
        if($mode==='custom'){$custom=ProcessingRecovery::sanitize(['pdf_dpi'=>$_POST['pdf_dpi']??null,'preview_width'=>$_POST['preview_width']??null,'thumbnail_width'=>$_POST['thumbnail_width']??null,'tile_size'=>$_POST['tile_size']??null,'ocr_timeout_seconds'=>$_POST['ocr_timeout_seconds']??null,'ocr_languages'=>$_POST['ocr_languages']??'auto','auto_language'=>!empty($_POST['auto_language'])?'on':'off']);$overrides=array_merge($overrides,$custom);}
        $profile=$mode==='custom'?'custom':(!empty($recommended['overrides'])?'recommended':'default');
        try{$jobGuid=QueueService::enqueueEditionRender($guid,'high',['processing_profile'=>$profile,'processing_overrides'=>$overrides,'reprocess_reason'=>substr((string)($issue['error']??'manual reprocess'),0,500)]);}catch(\RuntimeException $e){$this->adminError($e->getMessage());}
        Audit::log('edition.reprocessing_enqueued','edition',$guid,'SUCCESS',['job_guid'=>$jobGuid,'profile'=>$profile,'overrides'=>$overrides,'previous_issue'=>$issue]);Http::redirect('/admin/editions?reprocessing=1');
    }

    private function adminPublish(string $guid): never
    {
        $guard='epdi_ops_'.substr(hash('sha256',RequestContext::tenantGuid().'|'.$guid),0,40);if((int)Store::value('SELECT GET_LOCK(?,0)',[$guard])!==1)$this->adminError('Another edition action is in progress.');
        if(EditionOperations::active($guid))$this->adminError('Processing jobs are still active. Use Cancel processing or Recover first.');

        $row=Store::one('SELECT status FROM ep_editions WHERE tenant_guid=? AND edition_guid=?',[TenantData::tenantBin(),Uuid::toBinary($guid)]);if(!$row||!in_array($row['status'],['READY','SCHEDULED'],true))$this->adminError('Only ready editions can be published');
        Store::exec('UPDATE ep_editions SET status="PUBLISHED",publish_mode="MANUAL",scheduled_at=NULL,schedule_timezone=NULL,published_at=NOW(6),updated_at=NOW(6),version=version+1 WHERE tenant_guid=? AND edition_guid=?',[TenantData::tenantBin(),Uuid::toBinary($guid)]);Audit::log('edition.published','edition',$guid);RuntimeCache::broadcast(RequestContext::tenantGuid(),['dashboard','reader_state','public-editions']);RuntimeCache::queueWarm(RequestContext::tenantGuid(),$guid);Http::redirect('/admin/editions');
    }

    private function adminSchedule(string $guid): never
    {
        $guard='epdi_ops_'.substr(hash('sha256',RequestContext::tenantGuid().'|'.$guid),0,40);if((int)Store::value('SELECT GET_LOCK(?,0)',[$guard])!==1)$this->adminError('Another edition action is in progress.');
        if(EditionOperations::active($guid))$this->adminError('Processing jobs are still active. Use Cancel processing or Recover first.');

        $action=(string)($_POST['publish_action']??'schedule');
        if($action==='now')$this->adminPublish($guid);
        [$when,$tz]=$this->parseScheduledInput((string)($_POST['scheduled_at']??''),(string)($_POST['schedule_timezone']??Config::get('app.timezone','Asia/Kolkata')));
        $row=Store::one('SELECT status FROM ep_editions WHERE tenant_guid=? AND edition_guid=?',[TenantData::tenantBin(),Uuid::toBinary($guid)]);if(!$row||$row['status']!=='READY')$this->adminError('Only READY editions can be scheduled');
        Store::exec('UPDATE ep_editions SET status="SCHEDULED",publish_mode="SCHEDULED",schedule_timezone=?,scheduled_at=?,updated_at=NOW(6),version=version+1 WHERE tenant_guid=? AND edition_guid=?',[$tz,$when,TenantData::tenantBin(),Uuid::toBinary($guid)]);Audit::log('edition.scheduled','edition',$guid,'SUCCESS',['scheduled_at'=>$when,'schedule_timezone'=>$tz]);Http::redirect('/admin/editions?scheduled=1');
    }

    private function adminUnschedule(string $guid): never
    {
        $guard='epdi_ops_'.substr(hash('sha256',RequestContext::tenantGuid().'|'.$guid),0,40);if((int)Store::value('SELECT GET_LOCK(?,0)',[$guard])!==1)$this->adminError('Another edition action is in progress.');
        $row=Store::one('SELECT status,publish_mode FROM ep_editions WHERE tenant_guid=? AND edition_guid=?',[TenantData::tenantBin(),Uuid::toBinary($guid)]);if(!$row)$this->adminError('Edition not found');
        if((string)$row['publish_mode']!=='SCHEDULED')$this->adminError('This edition is not scheduled');
        $next=$row['status']==='SCHEDULED'?'READY':$row['status'];Store::exec('UPDATE ep_editions SET status=?,publish_mode="MANUAL",scheduled_at=NULL,schedule_timezone=NULL,updated_at=NOW(6),version=version+1 WHERE tenant_guid=? AND edition_guid=?',[$next,TenantData::tenantBin(),Uuid::toBinary($guid)]);Audit::log('edition.schedule.cancelled','edition',$guid);Http::redirect('/admin/editions?scheduled=1');
    }

    private function parseScheduledInput(string $raw,string $timezone): array
    {
        $raw=trim($raw);$timezone=trim($timezone);try{$tz=new \DateTimeZone($timezone);}catch(\Throwable){$this->adminError('Invalid schedule timezone');}
        try{$local=new \DateTimeImmutable($raw,$tz);}catch(\Throwable){$this->adminError('Choose a valid publication date and time');}
        if($local->getTimestamp()<=time())$this->adminError('Choose a future publication time');
        $appTz=new \DateTimeZone((string)Config::get('app.timezone','Asia/Kolkata'));return[$local->setTimezone($appTz)->format('Y-m-d H:i:s'),$timezone];
    }

    private function adminProcessing(): never
    {
        $rows=$this->processingRows();
        if(!empty($_GET['ajax']))Http::json(['ok'=>true,'version'=>$this->version(),'active'=>count(array_filter($rows,fn($r)=>in_array($r['status'],['QUEUED','RUNNING','RETRY_WAIT'],true))),'rows'=>$rows,'request_guid'=>Http::requestGuid()]);
        $notice='';
        if(!empty($_GET['started']))$notice='<div class="alert success">Edition queued. RabbitMQ will distribute render, asset and OCR work to Supervisor workers.</div>';
        if(!empty($_GET['queue_repaired']))$notice.='<div class="alert success">Queue dispatch repaired. Pending jobs were rechecked and eligible work was returned to the RabbitMQ outbox.</div>';
        $active=count(array_filter($rows,fn($r)=>in_array($r['status'],['QUEUED','RUNNING','RETRY_WAIT'],true)));
        $failed=count(array_filter($rows,fn($r)=>in_array($r['status'],['FAILED','NEEDS_ATTENTION'],true)));$stuck=count(array_filter($rows,fn($r)=>!empty($r['stale'])));
        $broker=RabbitMq::instance()->ping();$qstats=RabbitMq::instance()->queueStats();$outbox=QueueService::outboxBacklog();
        $brokerLabel=$broker['ok']?'Connected':$broker['detail'];
        $h='<section class="admin-head"><div><span class="eyebrow">OPERATIONS</span><h1>Processing Center</h1><p class="muted">Track edition progress, see what is waiting, and recover unfinished work.</p></div><div class="processing-live"><span class="processing-live-dot" aria-hidden="true"></span><span data-processing-live-label>'.($active?'Live updates':'Idle').'</span></div></section>'.$notice;
        $confirmRecoverable=(int)($outbox['recoverable_confirm_failed']??0);
        $failedLabel=$outbox['failed'].' failed'.($confirmRecoverable>0?' · '.$confirmRecoverable.' confirm-recoverable':'');
        $h.='<div class="kpis processing-kpis"><div class="kpi"><span>Active editions</span><strong data-processing-active>'.$active.'</strong></div><div class="kpi"><span>Needs attention</span><strong data-processing-failed>'.$failed.'</strong></div><div class="kpi"><span>No progress &gt;20 min</span><strong data-processing-stalled class="'.($stuck?'bad':'good').'">'.$stuck.'</strong></div><div class="kpi"><span>RabbitMQ</span><strong style="font-size:18px">'.$this->e($brokerLabel).'</strong></div><div class="kpi"><span>Outbox pending</span><strong>'.$outbox['pending'].'</strong><small>'.$outbox['processing'].' processing · '.$failedLabel.'</small></div></div>';if($stuck>0)$h.='<div class="alert danger"><strong>Stuck processing detected.</strong> '.$stuck.' edition(s) include queued or running work without progress for more than 20 minutes. Open the edition and use Process immediately to request direct recovery.</div>';
        if($outbox['pending']>0||$outbox['processing']>0||$outbox['failed']>0||($outbox['missing_dispatch_receipt']??0)>0){$age=(int)($outbox['oldest_pending_seconds']??0);$detail=(int)($outbox['failed_actionable']??0).' actionable failed · '.(int)($outbox['failed_closeable']??0).' historical/closeable · '.(int)($outbox['missing_dispatch_receipt']??0).' missing dispatch receipt';if($age>0)$detail.=' · oldest pending '.($age>=60?floor($age/60).' min':$age.' sec');$h.='<div class="alert warning"><strong>Queue transport needs analysis.</strong> '.$detail.' '.(Auth::canInfrastructureAdmin()?'<a class="btn" href="/admin/system/recovery">Open Web Recovery Center</a>':'<span class="muted">OWNER/ADMIN can run recovery actions.</span>').'</div>';}
        if($qstats){$h.='<div class="panel"><div class="section-head"><h2>Queue lanes</h2><span class="muted">Ready messages · Supervisor consumers</span></div><div class="queue-lanes">';foreach($qstats as$name=>$q)$h.='<div class="queue-lane"><code>'.$this->e($name).'</code><strong>'.(int)$q['ready'].'</strong><span>'.(int)$q['consumers'].' worker'.((int)$q['consumers']===1?'':'s').'</span></div>';$h.='</div></div>';}
        $h.='<div class="panel" data-processing-center><div class="table-wrap"><table class="processing-table"><thead><tr><th>Edition</th><th>Status</th><th>Overall</th><th>Stage progress</th><th>Last activity</th><th>Error / action</th></tr></thead><tbody data-processing-body>'.$this->processingRowsHtml($rows).'</tbody></table></div></div>';
        View::layout('Processing',$h,['brand'=>$this->brandName(),'admin'=>true]);
    }
    private function adminProcessingRepairQueue(): never
    {
        Auth::requireInfrastructureAdmin();if(!RateLimiter::allow('queue-repair:'.RequestContext::tenantGuid(),3,300))$this->adminError('Queue repair is temporarily rate-limited');
        $result=QueueService::repairQueueBacklog();Audit::log('queue.dispatch.safe_repair','tenant',RequestContext::tenantGuid(),'SUCCESS',$result);Http::redirect('/admin/system/recovery?repaired=1');
    }
    private function processingRows(): array
    {
        $editions=Store::all('SELECT DISTINCT e.edition_guid,e.edition_date,e.status,p.name publication_name,MAX(j.updated_at) last_activity FROM ep_editions e JOIN ep_processing_jobs j ON j.tenant_guid=e.tenant_guid AND j.edition_guid=e.edition_guid LEFT JOIN ep_publications p ON p.tenant_guid=e.tenant_guid AND p.publication_guid=e.publication_guid WHERE e.tenant_guid=? GROUP BY e.edition_guid,e.edition_date,e.status,p.name ORDER BY last_activity DESC LIMIT 50',[TenantData::tenantBin()]);
        $out=[];foreach($editions as$e){$editionGuid=$this->guid($e['edition_guid']);$p=QueueService::editionProgress($editionGuid);$all=$p['rows'];$status=(string)$e['status'];if(array_filter($all,fn($r)=>$r['status']==='RUNNING'))$status='RUNNING';elseif(array_filter($all,fn($r)=>$r['status']==='RETRY_WAIT'))$status='RETRY_WAIT';elseif(array_filter($all,fn($r)=>$r['status']==='QUEUED'))$status='QUEUED';elseif($status==='NEEDS_ATTENTION')$status='NEEDS_ATTENTION';elseif($status==='READY')$status='READY';$errors=array_values(array_filter(array_map(fn($r)=>trim((string)($r['error_message']??'')),$all)));$latest='';$attempt=1;foreach($all as$r){if((string)$r['updated_at']>$latest)$latest=(string)$r['updated_at'];$attempt=max($attempt,(int)$r['attempt_count']);}$stage='Render '.$p['render']['completed'].'/'.$p['render']['total'].' · Assets '.$p['assets']['completed'].'/'.$p['assets']['total'].' · OCR '.$p['ocr']['completed'].'/'.$p['ocr']['total'];if($p['ocr']['retry']||$p['assets']['retry'])$stage.=' · Retry '.($p['ocr']['retry']+$p['assets']['retry']);$stale=(bool)array_filter($all,fn($r)=>in_array($r['status'],['QUEUED','RUNNING','RETRY_WAIT'],true)&&(int)($r['age_seconds']??0)>EditionOperations::STALE_SECONDS);$out[]=['job_guid'=>$editionGuid,'edition_guid'=>$editionGuid,'edition'=>trim((string)$e['publication_name'].' '.(string)$e['edition_date']),'status'=>$status,'progress'=>$p['overall'],'stage'=>'PIPELINE','page'=>0,'total_pages'=>0,'message'=>$stage,'updated_at'=>$latest?:$e['last_activity'],'error'=>$errors?implode(' | ',array_slice(array_unique($errors),0,2)):'','stale'=>$stale,'attempt_count'=>$attempt];}return$out;
    }
    private function processingRowsHtml(array $rows): string
    {
        if(!$rows)return '<tr><td colspan="6"><div class="empty-inline">No processing jobs yet.</div></td></tr>';
        $h='';foreach($rows as$d){$pct=max(0,min(100,(float)$d['progress']));$action='';if(in_array($d['status'],['FAILED','NEEDS_ATTENTION'],true)||$d['stale'])$action='<form class="inline" method="post" action="/admin/editions/'.$this->e($d['edition_guid']).'/'.($d['stale']?'recover':'reprocess').'">'.$this->csrf().'<button class="console-icon-action is-process" title="'.($d['stale']?'Recover unfinished work':'Retry processing').'" aria-label="'.($d['stale']?'Recover unfinished work':'Retry processing').'">'.View::icon('refresh').'</button></form>';$err=$d['error']?'<span class="processing-error">'.$this->e($d['error']).'</span> ':'';$h.='<tr data-job-guid="'.$this->e($d['job_guid']).'"><td><a class="text-link" href="/admin/processing/'.$this->e($d['edition_guid']).'">'.$this->e($d['edition']).'</a></td><td><span class="status '.strtolower($d['status']).'">'.$this->e($d['status']).'</span>'.($d['stale']?' <span class="pill warning">STALE</span>':'').'</td><td><div class="processing-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'.$pct.'"><span style="width:'.$pct.'%"></span></div><div class="processing-progress-meta"><strong>'.number_format($pct,2).'%</strong><span>Attempt '.max(1,$d['attempt_count']).'</span></div></td><td>'.$this->e($d['message']?:'Waiting').'</td><td><time>'.$this->e($d['updated_at']).'</time></td><td>'.$err.$action.'</td></tr>';}
        return$h;
    }
    private function adminSubscribers(): never
    {
        $hasFlexible=SchemaDoctor::hasFlexibleReaderSchema();$hasTrusted=SchemaDoctor::hasTrustedAppSchema();
        $deviceCols=$hasFlexible?',d.installation_hash,d.expires_at device_expires_at':',NULL installation_hash,NULL device_expires_at';
        $deviceJoin=$hasFlexible?' LEFT JOIN ep_local_device_accounts d ON d.tenant_guid=s.tenant_guid AND d.user_guid=s.platform_user_guid':'';
        $trustedCols=$hasTrusted?',rd.trusted_device,COALESCE(rs.mobile_sessions,0) mobile_sessions,COALESCE(rs.desktop_sessions,0) desktop_sessions':',NULL trusted_device,0 mobile_sessions,0 desktop_sessions';
        $trustedJoin=$hasTrusted?' LEFT JOIN (SELECT tenant_guid,user_guid,MAX(device_label) trusted_device FROM ep_reader_devices WHERE device_type="MOBILE_APP" AND status="ACTIVE" GROUP BY tenant_guid,user_guid) rd ON rd.tenant_guid=s.tenant_guid AND rd.user_guid=s.platform_user_guid LEFT JOIN (SELECT tenant_guid,user_guid,SUM(CASE WHEN session_kind="MOBILE_APP" THEN 1 ELSE 0 END) mobile_sessions,SUM(CASE WHEN session_kind="DESKTOP_WEB" THEN 1 ELSE 0 END) desktop_sessions FROM ep_reader_sessions WHERE status="ACTIVE" GROUP BY tenant_guid,user_guid) rs ON rs.tenant_guid=s.tenant_guid AND rs.user_guid=s.platform_user_guid':'';
        $sql='SELECT s.subscriber_guid,s.platform_user_guid,s.status,s.created_at,i.email,i.display_name,i.identity_source,l.phone_e164'.$deviceCols.$trustedCols.' FROM ep_subscribers s LEFT JOIN ep_identities i ON i.platform_user_guid=s.platform_user_guid LEFT JOIN ep_local_mobile_accounts l ON l.tenant_guid=s.tenant_guid AND l.user_guid=s.platform_user_guid'.$deviceJoin.$trustedJoin.' WHERE s.tenant_guid=? ORDER BY s.created_at DESC LIMIT 200';
        $rows=TenantData::toGuidRows(Store::all($sql,[TenantData::tenantBin()]),['subscriber_guid','platform_user_guid']);
        $h='<section class="admin-head"><div><span class="eyebrow">AUDIENCE</span><h1>Subscribers</h1><p class="muted">Manage ePaper-local reader access, trusted app registration and active reader sessions. Mobile reader accounts remain separate from publisher/admin membership.</p></div></section>';
        if(!$hasFlexible||!$hasTrusted)$h.='<div class="alert danger"><strong>Database upgrade required.</strong><p>Reader identity tables for this EP-DI build are not fully installed. Subscriber access remains available in safe degraded mode, but trusted-device/session information is hidden until the schema is repaired.</p><a class="btn" href="/admin/system/upgrade">Open Upgrade Center</a></div>';
        $h.='<div class="panel"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Contact</th><th>Source</th><th>Status</th><th>Trusted app</th><th>Sessions</th><th>Since</th><th>Expiry</th><th>Actions</th></tr></thead><tbody>';
        foreach($rows as$r){$next=$r['status']==='ACTIVE'?'INACTIVE':'ACTIVE';$contact=trim((string)($r['phone_e164']??''))!==''?(string)$r['phone_e164']:(trim((string)($r['installation_hash']??''))!==''?'Device •'.strtoupper(substr((string)$r['installation_hash'],-6)):(string)($r['email']??''));$source=(string)($r['identity_source']??'PLATFORM');$trusted=trim((string)($r['trusted_device']??''));$sessions=$hasTrusted?'Mobile '.(int)($r['mobile_sessions']??0).' / 1 · Desktop '.(int)($r['desktop_sessions']??0).' / 1':'Schema repair required';$h.='<tr><td>'.$this->e($r['display_name']).'</td><td>'.$this->e($contact).'</td><td>'.$this->e($source).'</td><td><span class="status '.strtolower((string)$r['status']).'">'.$this->e($r['status']).'</span></td><td>'.$this->e($trusted!==''?$trusted:'—').'</td><td>'.$this->e($sessions).'</td><td>'.$this->e(date('d M Y',strtotime($r['created_at']))).'</td><td>'.$this->e(!empty($r['device_expires_at'])?date('d M Y',strtotime($r['device_expires_at'])):'—').'</td><td><form method="post" action="/admin/subscribers/'.$r['subscriber_guid'].'/status" class="inline">'.$this->csrf().'<input type="hidden" name="status" value="'.$next.'"><button class="text-btn">'.($next==='ACTIVE'?'Enable local access':'Disable local access').'</button></form></td></tr>';}
        $h.='</tbody></table></div><p class="muted">A verified local reader can have at most one active mobile-app session and one active desktop-web session. Disabling local access revokes both session kinds and the trusted app when the trusted-login schema is installed.</p></div>';View::layout('Subscribers',$h,['brand'=>$this->brandName(),'admin'=>true]);
    }
    private function adminSubscriberStatus(string $guid): never
    {
        $status=strtoupper((string)($_POST['status']??''));if(!in_array($status,['ACTIVE','INACTIVE'],true))$this->adminError('Invalid subscriber status');$bin=Uuid::toBinary($guid);$exists=Store::one('SELECT subscriber_guid,platform_user_guid FROM ep_subscribers WHERE tenant_guid=? AND subscriber_guid=?',[TenantData::tenantBin(),$bin]);if(!$exists)$this->adminError('Subscriber not found');Store::exec('UPDATE ep_subscribers SET status=?,updated_at=NOW(6) WHERE tenant_guid=? AND subscriber_guid=?',[$status,TenantData::tenantBin(),$bin]);if($status==='INACTIVE'&&SchemaDoctor::hasTrustedAppSchema()){$ug=Uuid::fromBinary($exists['platform_user_guid']);if($ug){ReaderSession::revokeKind($ug,ReaderSession::MOBILE);ReaderSession::revokeKind($ug,ReaderSession::DESKTOP);TrustedAppAuth::revokeForUser($ug);}}Audit::log('subscriber.status.updated','subscriber',$guid,'SUCCESS',['status'=>$status]);Http::redirect('/admin/subscribers?updated=1');
    }

    private function postedSetting(string $key,mixed $default=null,?bool &$present=null): mixed
    {
        $present=false;
        if(isset($_POST['settings'])&&is_array($_POST['settings'])&&array_key_exists($key,$_POST['settings'])){$present=true;return$_POST['settings'][$key];}
        if(array_key_exists($key,$_POST)){$present=true;return$_POST[$key];}
        $normalized=str_replace(['.',' '],'_',$key);
        if(array_key_exists($normalized,$_POST)){$present=true;return$_POST[$normalized];}
        return$default;
    }

