            Audit::log('brand.settings.updated','settings',RequestContext::tenantGuid(),'SUCCESS',['assets'=>array_keys(array_filter($_FILES,fn($f)=>is_array($f)&&($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK))]);Http::redirect('/admin/settings/brand?saved=1');
        }
        $tabs='';foreach(SettingsCatalog::groups() as$key=>$g)$tabs.='<a class="settings-tab '.($key==='brand'?'active':'').'" href="/admin/settings/'.$this->e($key).'">'.$this->e($g['label']).'</a>';
        $siteName=(string)TenantData::setting('brand.site_name',$this->brandName());$tagline=(string)TenantData::setting('brand.tagline','Digital newspaper');$accent=(string)TenantData::setting('brand.accent','#2563eb');$footer=(string)TenantData::setting('brand.footer_text','');
        $h='<section class="admin-head"><div><span class="eyebrow">PUBLISHER CONTROL</span><h1>Brand & identity</h1><p class="muted">Upload publisher assets directly. ePaper SaaS validates, optimizes and stores them per tenant—no file URL knowledge required.</p></div></section><nav class="settings-tabs">'.$tabs.'</nav>'.(!empty($_GET['saved'])?'<div class="alert success">Brand settings and assets updated.</div>':'').(!empty($_GET['asset_removed'])?'<div class="alert success">Brand asset removed.</div>':'').'<form method="post" enctype="multipart/form-data" class="brand-settings-stack">'.$this->csrf().'<section class="panel"><div class="section-head"><div><span class="eyebrow">IDENTITY</span><h2>Publisher identity</h2></div></div><div class="form-grid"><label>Site name<input name="settings[brand.site_name]" value="'.$this->e($siteName).'" required maxlength="120"></label><label>Tagline<input name="settings[brand.tagline]" value="'.$this->e($tagline).'" maxlength="180"></label><label>Accent color<div class="color-field"><input type="color" data-brand-color value="'.$this->e($accent).'"><input name="settings[brand.accent]" data-brand-color-text value="'.$this->e($accent).'" pattern="#[0-9A-Fa-f]{6}" required></div></label><label>Footer text<input name="settings[brand.footer_text]" value="'.$this->e($footer).'" maxlength="220"></label></div></section><section class="panel"><div class="section-head"><div><span class="eyebrow">ASSETS</span><h2>Logo & app assets</h2><p class="muted">Replace assets simply by selecting a new file and saving. Existing public URLs are managed automatically.</p></div></div><div class="brand-asset-grid">';
        foreach($assetDefs as$slot=>$def){$current=trim((string)TenantData::setting($def['setting'],''));$h.='<article class="brand-asset-card"><div class="brand-asset-preview '.($current?'has-image':'is-empty').'">'.($current?'<img src="'.$this->e($current).'" alt="'.$this->e($def['label']).' preview">':'<span>No asset uploaded</span>').'</div><div class="brand-asset-copy"><strong>'.$this->e($def['label']).'</strong><p>'.$this->e($def['hint']).'</p></div><label class="brand-upload-button">Choose file<input type="file" name="'.$this->e($slot).'" accept="image/png,image/jpeg,image/webp" data-brand-file></label>'.($current?'<button class="text-btn danger" type="submit" name="slot" value="'.$this->e($slot).'" formaction="/admin/settings/brand?brand_action=remove_asset" formnovalidate data-brand-remove data-slot="'.$this->e($slot).'">Remove</button>':'').($current?'<small class="asset-path">Managed asset</small>':'').'</article>';}
