    private function brandAssetDirectory(): string
    {
        $tenant=preg_replace('/[^0-9a-f-]/i','',RequestContext::tenantGuid());$dir=dirname(__DIR__).'/public_html/uploads/branding/'.$tenant;if(!is_dir($dir)&&!@mkdir($dir,0775,true)&&!is_dir($dir))$this->adminError('Could not create the tenant branding directory');return$dir;
    }
    private function storeBrandAsset(string $slot,array $file): string
    {
        $err=(int)($file['error']??UPLOAD_ERR_NO_FILE);if($err!==UPLOAD_ERR_OK)$this->adminError('Brand asset upload failed (upload error '.$err.')');$size=(int)($file['size']??0);if($size<1||$size>8*1024*1024)$this->adminError('Brand assets must be smaller than 8 MB');$tmp=(string)($file['tmp_name']??'');if(!is_uploaded_file($tmp)&&!is_file($tmp))$this->adminError('Uploaded brand asset is unavailable');$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($tmp);$allowed=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];if(!isset($allowed[$mime]))$this->adminError('Use a PNG, JPEG or WebP image');$info=@getimagesize($tmp);if(!$info||($info[0]??0)<16||($info[1]??0)<16||($info[0]??0)>8000||($info[1]??0)>8000)$this->adminError('Brand image dimensions are invalid or too large');$dir=$this->brandAssetDirectory();$stamp=time();
        if(class_exists('Imagick')){try{$im=new \Imagick($tmp);if(method_exists($im,'autoOrient'))$im->autoOrient();$im->setImageColorspace(\Imagick::COLORSPACE_SRGB);$im->stripImage();if(in_array($slot,['logo','logo_dark'],true)){$im->thumbnailImage(1600,420,true,true);$im->setImageFormat('webp');$im->setImageCompressionQuality(91);$name=$slot==='logo'?'logo.webp':'logo-dark.webp';$target=$dir.'/'.$name;$temp=$target.'.tmp';$im->writeImage($temp);@rename($temp,$target);$im->clear();return'/uploads/branding/'.RequestContext::tenantGuid().'/'.$name.'?v='.$stamp;}if($slot==='mark'){$canvas=$this->squareBrandCanvas($im,512);$target=$dir.'/mark.webp';$canvas->setImageFormat('webp');$canvas->setImageCompressionQuality(91);$canvas->writeImage($target);$this->writeSquarePng($canvas,$dir.'/favicon-32.png',32);$this->writeSquarePng($canvas,$dir.'/apple-touch-icon.png',180);$this->writeSquarePng($canvas,$dir.'/pwa-192.png',192);$this->writeSquarePng($canvas,$dir.'/pwa-512.png',512);$canvas->clear();$im->clear();return'/uploads/branding/'.RequestContext::tenantGuid().'/mark.webp?v='.$stamp;}if($slot==='favicon'){$canvas=$this->squareBrandCanvas($im,128);$this->writeSquarePng($canvas,$dir.'/favicon.png',64);$canvas->clear();$im->clear();return'/uploads/branding/'.RequestContext::tenantGuid().'/favicon.png?v='.$stamp;}}catch(\Throwable $e){$this->adminError('Could not optimize brand asset: '.$e->getMessage());}}
        $ext=$allowed[$mime];$name=match($slot){'logo'=>'logo.'.$ext,'logo_dark'=>'logo-dark.'.$ext,'mark'=>'mark.'.$ext,'favicon'=>'favicon.'.$ext,default=>$slot.'.'.$ext};$target=$dir.'/'.$name;if(!@copy($tmp,$target))$this->adminError('Could not store the uploaded brand asset');return'/uploads/branding/'.RequestContext::tenantGuid().'/'.$name.'?v='.$stamp;
    }
    private function squareBrandCanvas(\Imagick $source,int $size): \Imagick
    {
        $src=clone$source;$src->setImageBackgroundColor(new \ImagickPixel('transparent'));$src->thumbnailImage($size,$size,true,true);$canvas=new \Imagick();$canvas->newImage($size,$size,new \ImagickPixel('transparent'),'png');$x=(int)(($size-$src->getImageWidth())/2);$y=(int)(($size-$src->getImageHeight())/2);$canvas->compositeImage($src,\Imagick::COMPOSITE_OVER,$x,$y);$src->clear();return$canvas;
    }
    private function writeSquarePng(\Imagick $source,string $target,int $size): void
    {
        $im=clone$source;$im->resizeImage($size,$size,\Imagick::FILTER_LANCZOS,1);$im->setImageFormat('png');$im->stripImage();$im->writeImage($target);$im->clear();
    }
    private function removeBrandAsset(string $slot,string $setting,?string $userGuid): void
    {
        $dir=$this->brandAssetDirectory();$patterns=match($slot){'logo'=>['logo.*'],'logo_dark'=>['logo-dark.*'],'mark'=>['mark.*','favicon-32.png','apple-touch-icon.png','pwa-192.png','pwa-512.png'],'favicon'=>['favicon.*'],default=>[]};foreach($patterns as$pattern)foreach(glob($dir.'/'.$pattern)?:[] as$f)if(is_file($f))@unlink($f);TenantData::setSetting($setting,'',$userGuid);if($slot==='mark'){$favicon=(string)TenantData::setting('brand.favicon_path','');foreach(['brand.apple_touch_icon_path','brand.pwa_icon_192_path','brand.pwa_icon_512_path'] as$key)TenantData::setSetting($key,'',$userGuid);if(str_contains($favicon,'/favicon-32.png'))TenantData::setSetting('brand.favicon_path','',$userGuid);}
    }

