        $sel=function(string$key,string$label,array$options,string$hint='')use(&$v){$o='<label>'.$this->e($label).'<select name="settings['.$this->e($key).']">';foreach($options as$value=>$text){if(is_int($value))$value=(string)$text;$o.='<option value="'.$this->e((string)$value).'"'.(($v[$key]??'')===(string)$value?' selected':'').'>'.$this->e((string)$text).'</option>';}$o.='</select>'.($hint!==''?'<small>'.$this->e($hint).'</small>':'').'</label>';return$o;};
