        $autoRescue=($v['processing.recovery_auto_rescue']??'off')==='on';
        $h='<section class="admin-head processing-settings-head"><div><span class="eyebrow">PUBLISHER CONTROL</span><h1>Processing</h1><p class="muted">Configure default media generation, OCR and safe recovery behavior. One-off Reprocess overrides never mutate these publisher defaults.</p></div><span class="pill">Global default</span></section><nav class="settings-tabs">'.$tabs.'</nav>'.(!empty($_GET['saved'])?'<div class="alert success">Processing settings saved. New processing runs will use the updated defaults.</div>':'');
        $h.='<form method="post" class="processing-settings-form" data-processing-settings>'.$this->csrf();
        $h.='<section class="processing-preset-bar"><div><span class="eyebrow">SAFE PRESETS</span><strong>Start from a tested processing profile</strong><small>Presets only change fields in this form. Nothing is saved until you click Save Processing.</small></div><div class="processing-preset-actions"><button type="button" class="btn ghost" data-processing-preset="recommended">Recommended</button><button type="button" class="btn ghost" data-processing-preset="quality">High fidelity</button><button type="button" class="btn ghost" data-processing-preset="recovery">Low-memory recovery</button></div><span class="processing-preset-state" data-processing-preset-state hidden>Unsaved preset</span></section>';
