        if(!empty($sch['history'])){$h.='<div class="recovery-history"><strong>Recent scheduler runs</strong><div>';foreach(array_reverse(array_slice((array)$sch['history'],-10)) as$e)$h.='<span>'.$this->e((string)($e['source']??'?')).' · '.$this->e((string)($e['at']??'')).' · published '.(int)($e['published_now']??0).'</span>';$h.='</div></div>';}$h.='</section>';
        $h.='<section class="panel recovery-section"><div class="section-head"><div><span class="eyebrow">QUEUE & OUTBOX</span><h2>Safe transport reconciliation</h2><p class="muted">A PROCESSED QUEUE_PUBLISH event is a successful dispatch receipt. Queued jobs with confirmed receipts are assumed to be waiting in RabbitMQ and are not duplicated.</p></div></div><div class="recovery-grid"><div class="recovery-metric"><span>DB queued / retry</span><strong>'.(int)$dispatch['db_queued'].' / '.(int)$dispatch['db_retry_wait'].'</strong></div><div class="recovery-metric"><span>Dispatch confirmed</span><strong>'.(int)$dispatch['dispatch_confirmed'].'</strong></div><div class="recovery-metric"><span>Pending / processing</span><strong>'.(int)$dispatch['dispatch_pending'].' / '.(int)$dispatch['dispatch_processing'].'</strong></div><div class="recovery-metric"><span>Failed dispatch</span><strong>'.(int)$dispatch['dispatch_failed'].'</strong></div><div class="recovery-metric"><span>Missing receipt</span><strong>'.(int)$dispatch['missing_dispatch_receipt'].'</strong></div><div class="recovery-metric"><span>Historical failed rows</span><strong>'.(int)$fc['total'].'</strong></div></div>';
        $h.='<div class="recovery-classify"><span><b>'.(int)$fc['close_terminal'].'</b> terminal</span><span><b>'.(int)$fc['close_orphan'].'</b> orphan</span><span><b>'.(int)$fc['close_superseded'].'</b> superseded</span><span><b>'.(int)$fc['close_probe'].'</b> probe</span><span><b>'.(int)$fc['recover_confirm'].'</b> confirm-recoverable</span><span><b>'.(int)$fc['unknown_active'].'</b> unknown active</span><span><b>'.(int)$fc['invalid_payload'].'</b> invalid payload</span></div>';
        $h.='<div class="two-col"><form method="post" action="/admin/system/recovery/reconcile" class="recovery-form recovery-confirm">'.$this->csrf().'<label><input type="checkbox" name="confirm" value="1" required> Apply only safe close/recover classifications; leave unknown failures unchanged.</label><button class="btn primary" type="submit">Apply safe reconcile</button></form><form method="post" action="/admin/system/recovery/repair-missing" class="recovery-form recovery-confirm">'.$this->csrf().'<label><input type="checkbox" name="confirm" value="1" required> Create outbox events only for jobs with no QUEUE_PUBLISH history.</label><button class="btn" type="submit"'.((int)$dispatch['missing_dispatch_receipt']===0?' disabled':'').'>Repair missing dispatches</button></form></div>';
        if(!empty($fc['unknown_active'])||!empty($fc['invalid_payload']))$h.='<div class="alert warning"><strong>Manual review preserved.</strong> '.((int)$fc['unknown_active']+(int)$fc['invalid_payload']).' failure(s) are not auto-repaired because their transport state is ambiguous.</div>';
