    private function adminSupervisorSetup(): never
    {
        Auth::requireInfrastructureAdmin();
        $pre=SupervisorRuntime::preflight();$diag=SupervisorRuntime::diagnosis();$cli=SupervisorRuntime::cliPreflight();$commands=SupervisorRuntime::commands();$expected=SupervisorRuntime::expected();$root=SupervisorRuntime::appRoot();
        $allHealthy=(bool)($diag['ok']??false);$preOk=(bool)($pre['ok']??false);
        $h='<section class="admin-head"><div><span class="eyebrow">RUNTIME & PUBLISHING ENGINE</span><h1>Supervisor setup & worker doctor</h1><p class="muted">Diagnose the 6 long-running publishing processes, generate exact server-specific commands and verify the CLI runtime without exposing RabbitMQ or Redis credentials.</p></div><div class="page-head-actions"><a class="btn ghost" href="/admin/system/infrastructure">Infrastructure</a><a class="btn primary" href="/admin/system/infrastructure/supervisor.conf">Download config</a></div></section>';
        $h.='<div class="alert '.($allHealthy?'success':($preOk?'warning':'danger')).'"><strong>'.($allHealthy?'Supervisor runtime healthy':($preOk?'Runtime is ready; Supervisor processes still need attention':'Fix runtime prerequisites before starting workers')).'</strong><br>'.($allHealthy?'All configured worker capacity is visible through heartbeat and broker signals.':($preOk?'The application, RabbitMQ and worker scripts are ready. Use the exact commands below, then wait 15 seconds and refresh this page.':'One or more required prerequisites failed. Review the preflight checks below.')).'</div>';

        $h.='<section class="panel"><div class="section-head"><div><span class="eyebrow">LIVE DIAGNOSIS</span><h2>Worker lanes</h2><p class="muted">Heartbeat source: '.$this->e((string)($diag['heartbeat_source']??'unknown')).'. RabbitMQ consumer counts are checked independently so a missing process can be distinguished from a heartbeat-only problem.</p></div><a class="btn ghost" href="/admin/system/infrastructure/supervisor">Refresh</a></div><div class="worker-health-list">';
        foreach(($diag['lanes']??[]) as$lane=>$d){$status=(string)($d['status']??'UNKNOWN');$ok=$status==='HEALTHY';$cons=$d['consumers'];$signal='Heartbeat '.(int)$d['heartbeat'].' / '.(int)$d['expected'].($cons===null?'':' · Rabbit consumers '.(int)$cons.' / '.(int)$d['expected']);$h.='<div class="worker-health-row"><span><strong>'.$this->e(ucfirst((string)$lane)).'</strong><small>'.$this->e((string)$d['message']).'</small></span><strong class="'.($ok?'good':'bad').'">'.$this->e($status).'</strong><small>'.$this->e($signal).'</small></div>';}
        $h.='</div></section>';

        $h.='<section class="panel"><div class="section-head"><div><span class="eyebrow">PREFLIGHT</span><h2>Application & CLI readiness</h2><p class="muted">These checks are safe and do not create long-running processes.</p></div><span class="pill">'.($preOk?'READY':'ATTENTION').'</span></div><div class="health-grid">';
        foreach(($pre['checks']??[]) as$name=>$c){$ok=(bool)($c['ok']??false);$required=(bool)($c['required']??true);$h.='<div class="health-card"><span>'.$this->e((string)$name).'</span><strong class="'.($ok?'good':($required?'bad':'')).'">'.($ok?'PASS':($required?'FAIL':'OPTIONAL')).'</strong><small>'.$this->e((string)($c['detail']??'')).'</small></div>';}
        $h.='</div>';
        if(is_array($cli)){$h.='<div class="alert '.(!empty($cli['ok'])?'success':'warning').'"><strong>CLI cross-check: '.(!empty($cli['ok'])?'PASS':'ATTENTION').'</strong><br>The web process invoked <code>'.$this->e((string)($pre['php']['path']??'php')).' '.$this->e($root).'/bin/supervisor-preflight.php --json</code> and received exit code '.(int)($cli['exit_code']??0).'.</div>';}
        else{$h.='<div class="alert warning"><strong>CLI cross-check not available from PHP-FPM.</strong><br>Run <code>php '.$this->e($root).'/bin/supervisor-preflight.php</code> once over SSH before creating the Supervisor jobs.</div>';}
        $h.='</section>';

        $h.='<section class="panel"><div class="section-head"><div><span class="eyebrow">EXACT SERVER COMMANDS</span><h2>Create these Supervisor programs</h2><p class="muted">Application root: <code>'.$this->e($root).'</code>. The commands are generated from the deployed path, not from a placeholder.</p></div><a class="text-btn" href="/admin/system/infrastructure/supervisor.conf">Download .conf</a></div><div class="record-stack">';
        foreach($commands as$lane=>$command){$h.='<div class="record-row"><div><strong>'.$this->e(ucfirst($lane)).'</strong><p>Processes: '.(int)($expected[$lane]??1).($lane==='assets'?' · higher concurrency for image assets':'').'</p><code>'.$this->e($command).'</code></div><span>'.(int)($expected[$lane]??1).'×</span></div>';}
        $h.='</div><div class="alert warning"><strong>Security boundary:</strong> this web page intentionally does not call <code>supervisorctl</code>, fork daemons or write operating-system Supervisor configuration. Add these programs through the Cloudways/server Supervisor control plane, then let the application verify them through broker consumers and expiring heartbeats.</div></section>';

        $config=SupervisorRuntime::config();$h.='<section class="panel"><div class="section-head"><div><span class="eyebrow">GENERATED CONFIGURATION</span><h2>Supervisor configuration</h2><p class="muted">Credential-free; safe to download and hand to the server control plane.</p></div></div><pre style="white-space:pre-wrap;overflow:auto;max-height:540px;padding:18px;border:1px solid var(--border);border-radius:12px;background:var(--surface-soft,#f8f9fb)">'.$this->e($config).'</pre></section>';

        $h.='<section class="panel"><span class="eyebrow">VERIFY</span><h2>After starting the jobs</h2><ol><li>Wait at least 15 seconds for worker heartbeats.</li><li>Refresh this Worker Doctor. Target: Outbox 1/1, Render 1/1, Assets 2/2, OCR 1/1, Finalize 1/1.</li><li>Open Infrastructure and confirm RabbitMQ consumer counts match the expected lanes.</li><li>Run the end-to-end worker pipeline test. It must pass Outbox → RabbitMQ → Render / Assets / OCR / Finalize.</li><li>Recheck System Health. Supervisor workers should change from ATTENTION to HEALTHY.</li></ol><div class="form-actions"><a class="btn primary" href="/admin/system/infrastructure">Open Infrastructure & run test</a><a class="btn ghost" href="/admin/system/health">System health</a></div></section>';
        View::layout('Supervisor setup',$h,['brand'=>$this->brandName(),'admin'=>true]);
    }

    private function adminSupervisorConfigDownload(): never
    {
        Auth::requireInfrastructureAdmin();Http::privateNoStore();$body=SupervisorRuntime::config();
        header('Content-Type: text/plain; charset=utf-8');header('Content-Disposition: attachment; filename="EP-DI-supervisor.conf"');header('X-Content-Type-Options: nosniff');header('Content-Length: '.strlen($body));echo$body;exit;
    }

    private function adminInfrastructureSave(): never
    {
        Auth::requireInfrastructureAdmin();try{InfrastructureConfig::saveRabbit($_POST);$repair=null;if(strtolower((string)($_POST['driver']??''))==='rabbitmq')$repair=QueueService::repairQueueBacklog();Audit::log('infrastructure.rabbitmq.updated','application',null,'SUCCESS',['driver'=>$_POST['driver']??null,'host'=>$_POST['host']??null,'port'=>(int)($_POST['port']??0),'vhost'=>$_POST['vhost']??null,'username'=>$_POST['username']??null,'queue_repair'=>$repair]);Http::redirect('/admin/system/infrastructure?saved=1');}catch(\Throwable$e){$this->adminInfrastructure(['ok'=>false,'detail'=>$e->getMessage()],$_POST);}
    }
    private function adminInfrastructureMediaSave(): never
    {
        Auth::requireInfrastructureAdmin();try{InfrastructureConfig::saveMedia($_POST);Audit::log('infrastructure.media.updated','application',null,'SUCCESS',['token_bucket_seconds'=>(int)($_POST['token_bucket_seconds']??300),'x_accel_enabled'=>trim((string)($_POST['x_accel_prefix']??''))!=='']);Http::redirect('/admin/system/infrastructure?media_saved=1');}catch(\Throwable$e){$this->adminError($e->getMessage());}
    }
    private function adminInfrastructureRabbitTest(): never
    {
        Auth::requireInfrastructureAdmin();$test=InfrastructureConfig::testRabbit($_POST);Audit::log('infrastructure.rabbitmq.test','application',null,$test['ok']?'SUCCESS':'FAILED',['host'=>$_POST['host']??null,'port'=>(int)($_POST['port']??0),'vhost'=>$_POST['vhost']??null]);$this->adminInfrastructure($test,$_POST);
    }
    private function adminInfrastructureProbe(): never
    {
        Auth::requireInfrastructureAdmin();if(!QueueService::rabbitEnabled())$this->adminError('RabbitMQ must be the active queue driver before running the worker pipeline test.');$probe=InfrastructureConfig::createProbe();Audit::log('infrastructure.worker_probe.started','application',$probe);Http::redirect('/admin/system/infrastructure?probe='.rawurlencode($probe));
    }
    private function adminInfrastructureProbeStatus(): never
    {
        Auth::requireInfrastructureAdmin();$probe=(string)($_GET['probe']??'');Http::json(InfrastructureConfig::probeStatus($probe));
    }
    private function healthReady(): never
    {
        $checks=$this->healthChecks(false);$ok=!in_array(false,array_column($checks,'ok'),true);Http::json(['ok'=>$ok,'status'=>$ok?'READY':'DEGRADED','version'=>$this->version(),'checks'=>$checks,'request_guid'=>Http::requestGuid()],$ok?200:503);
    }
    private function healthChecks(bool $platformTenant=true): array
    {
        $c=[];try{Store::value('SELECT 1');$c['MariaDB']=['ok'=>true,'detail'=>'Connected'];}catch(\Throwable$e){$c['MariaDB']=['ok'=>false,'detail'=>$e->getMessage()];}$r=\EpaperSaas\Core\RedisStore::enabled();try{$ping=$r?\EpaperSaas\Core\RedisStore::client()?->ping():null;$c['Redis']=['ok'=>!$r||$ping!==false,'detail'=>$r?'Connected':'Disabled'];}catch(\Throwable$e){$c['Redis']=['ok'=>false,'detail'=>$e->getMessage()];}try{$ph=PlatformClient::instance()->health();$c['Digiti Platform']=['ok'=>(bool)($ph['ok']??false),'detail'=>$ph['status']??'Unavailable'];}catch(\Throwable$e){$c['Digiti Platform']=['ok'=>false,'detail'=>$e->getMessage()];}$root=dirname(__DIR__);$c['Storage']=['ok'=>is_writable($root.'/storage'),'detail'=>is_writable($root.'/storage')?'Writable':'Not writable'];foreach(['pdftoppm','tesseract'] as$cmd)$c[$cmd]=$this->commandCheck($cmd);$c['Imagick']=['ok'=>class_exists('Imagick'),'detail'=>class_exists('Imagick')?'Available':'PHP Imagick unavailable'];if(QueueService::rabbitEnabled()){$q=RabbitMq::instance()->ping();$c['RabbitMQ']=$q;if($platformTenant){$o=QueueService::outboxBacklog();$queueOk=(int)($o['failed_actionable']??0)===0&&(int)($o['missing_dispatch_receipt']??0)===0&&(int)($o['oldest_pending_seconds']??0)<=300;$c['Queue Outbox']=['ok'=>$queueOk,'detail'=>(int)$o['pending'].' pending · '.(int)($o['failed_actionable']??0).' actionable failed · '.(int)($o['failed_closeable']??0).' historical · '.(int)($o['missing_dispatch_receipt']??0).' missing receipt'];}else{$last=Store::value('SELECT state_value FROM ep_system_state WHERE state_key="queue.outbox_last_run"');$lr=$last?json_decode((string)$last,true):null;$c['Queue Outbox']=['ok'=>true,'detail'=>is_array($lr)?((int)($lr['published']??0).' published · '.(int)($lr['failed']??0).' failed on last run'):'Awaiting first publisher heartbeat'];}}return$c;
    }
    private function commandCheck(string $cmd): array
    {
        if(!function_exists('exec'))return['ok'=>false,'detail'=>'PHP exec() is disabled'];
        $out=[];$code=127;
        try{exec('command -v '.escapeshellarg($cmd).' 2>/dev/null',$out,$code);}catch(\Throwable$e){return['ok'=>false,'detail'=>'Command check unavailable: '.$e->getMessage()];}
        return['ok'=>$code===0,'detail'=>$code===0?'Available':'Not installed'];
    }
    private function recordMenu(string $content): string
    {
        return'<details class="record-menu"><summary aria-label="Record actions">•••</summary><div class="record-popover">'.$content.'</div></details>';
    }
    private function adminError(string $message): never{http_response_code(422);View::layout('Request needs attention','<section class="empty-state request-attention"><span class="eyebrow">REQUEST NEEDS ATTENTION</span><h1>We could not complete this change</h1><p>'.$this->e($message).'</p><p class="muted">Request: <code>'.$this->e(Http::requestGuid()).'</code></p><a class="btn" href="javascript:history.back()">Go back</a></section>',['brand'=>$this->brandName(),'admin'=>true]);}
    private function notFound(string $message): never{http_response_code(404);View::layout('Unavailable','<section class="empty-state"><h1>'.$this->e($message).'</h1><a class="btn" href="/">Back to ePaper</a></section>',['brand'=>$this->brandName()]);}
    private function slug(string $v): string{$v=mb_strtolower(trim($v));$v=preg_replace('/[^a-z0-9]+/u','-',$v);return trim((string)$v,'-');}
}
